SELECT DATE_TRUNC('WEEK', launch_date) AS week_start, CASE WHEN cost >= 550 THEN 'HIGH' ELSE 'LOW' END AS cost_tier, PERCENTILE_APPROX(cost, 0.9) AS cost_p90, SIZE(COLLECT_SET(brand)) AS num_brands, MIN(stock_qty) AS min_stock_qty, BIT_AND(stock_qty) AS stock_qty_bit_and, APPROX_PERCENTILE(stock_qty, ARRAY(0.25, 0.5, 0.75)) AS stock_qty_quartiles FROM products GROUP BY DATE_TRUNC('WEEK', launch_date), CASE WHEN cost >= 550 THEN 'HIGH' ELSE 'LOW' END
